// ════════════════════════════════════════════
// GLOBAL STATE
// ════════════════════════════════════════════
let PRODS    = [];   // live from Firestore
let RATES    = { gold24:7420, gold22:6803, gold18:5565, silver:89.5 };
let SETTINGS = {
  storeName:'NM Jewellers', gst:'27XXXXX1234X1Z5',
  phone:'+91 98765 43210', whatsapp:'919876543210',
  email:'info@nmjewellers.in', city:'Pune',
  address:'Saraf Bazar , Bhusawal – 425201',
  hours:'Mon-Sun: 10:00 AM – 8:00 PM | Tuesday: Closed',
  tagline:'Since1 2016 · BIS Hallmarked'
};
