let WISHLIST = new Set();
let FILT     = [];
let HERO_IDX = 0;
let IS_ADMIN = false;

// ════════════════════════════════════════════
// PRICE ENGINE
// ════════════════════════════════════════════
function getRate(metal){
  if(metal.includes('24K')) return RATES.gold24;
  if(metal.includes('22K')) return RATES.gold22;
  if(metal.includes('18K')) return RATES.gold18;
  if(metal.includes('Silver')) return RATES.silver;
  return RATES.gold18;
}
function calcPrice(p){
  const r=getRate(p.metal), mv=p.wt*r, mk=p.wt*p.mc, sub=mv+mk, gst=sub*.03, tot=sub+gst;
  return {r,mv,mk,gst,tot};
}
function fmt(n){ return '₹'+Math.round(n).toLocaleString('en-IN'); }

// ════════════════════════════════════════════
// FIRESTORE — REAL-TIME LISTENERS
// ════════════════════════════════════════════
function startListeners(){
  // Products — live sync
  onSnapshot(query(collection(db,'products'), orderBy('id')), snap => {
    PRODS = snap.docs.map(d => ({...d.data(), _docId: d.id}));
    FILT  = [...PRODS];
    renderFeatured();
    renderMain();
    if(IS_ADMIN){ renderAdminProducts(); renderInventory(); renderTopProducts(); updateDashStats(); }
  });

  // Rates — live sync
  onSnapshot(doc(db,'rates','current'), snap => {
    if(snap.exists()){
      const d = snap.data();
      RATES = { gold24:d.gold24, gold22:d.gold22, gold18:d.gold18, silver:d.silver };
      updateRateTicker();
      if(IS_ADMIN) updateAdminRateDisplay();
    }
  });

  // Settings — live sync
  onSnapshot(doc(db,'settings','store'), snap => {
    if(snap.exists()){
      SETTINGS = {...SETTINGS, ...snap.data()};
      applySettings();
    }
  });

  // Orders — admin only (called after login)
}

function listenOrders(){
  onSnapshot(query(collection(db,'orders'), orderBy('createdAt','desc'), limit(50)), snap => {
    const orders = snap.docs.map(d => ({...d.data(), _docId:d.id}));
    renderOrderTables(orders);
    updateDashStats();
  });
}

// ════════════════════════════════════════════
// FIRESTORE — WRITE OPERATIONS
// ════════════════════════════════════════════
async function fbSaveProduct(p){
  try {
    await setDoc(doc(db,'products',p.id), {
      id:p.id, name:p.name, cat:p.cat, metal:p.metal,
      wt:parseFloat(p.wt), mc:parseFloat(p.mc), stock:parseInt(p.stock),
      tag:p.tag||'', img:p.img, desc:p.desc,
      updatedAt: serverTimestamp()
    });
    return true;
  } catch(e){ toast('❌ Error: '+e.message); return false; }
}

async function fbDeleteProduct(docId){
  try { await deleteDoc(doc(db,'products',docId)); return true; }
  catch(e){ toast('❌ Error: '+e.message); return false; }
}

async function fbUpdateStock(docId, newStock){
  try {
    await updateDoc(doc(db,'products',docId), { stock:newStock, updatedAt:serverTimestamp() });
    return true;
  } catch(e){ toast('❌ '+e.message); return false; }
}

async function fbSaveRates(r){
  try {
    await setDoc(doc(db,'rates','current'), { ...r, updatedAt:serverTimestamp() });
    return true;
  } catch(e){ toast('❌ '+e.message); return false; }
}

async function fbSaveSettings(s){
  try {
    await setDoc(doc(db,'settings','store'), { ...s, updatedAt:serverTimestamp() });
    return true;
  } catch(e){ toast('❌ '+e.message); return false; }
}

async function fbPlaceOrder(orderData){
  try {
    const ref = await addDoc(collection(db,'orders'), {
      ...orderData, status:'Pending', createdAt:serverTimestamp()
    });
    // Reduce stock for each cart item
    for(const item of CART){
      const prod = PRODS.find(p=>p.id===item.id);
      if(prod && prod.stock > 0){
        await fbUpdateStock(prod._docId, prod.stock - 1);
      }
    }
    return ref.id;
  } catch(e){ toast('❌ Order error: '+e.message); return null; }
}

async function fbUpdateOrderStatus(docId, status){
  try {
    await updateDoc(doc(db,'orders',docId), { status, updatedAt:serverTimestamp() });
    toast('✅ Order status updated to: '+status);
  } catch(e){ toast('❌ '+e.message); }
}

