// ════════════════════════════════════════════
// AUTH
// ════════════════════════════════════════════
onAuthStateChanged(auth, user => {
  IS_ADMIN = !!user;
  if(user){
    document.getElementById('adminLogin').classList.remove('on');
    document.getElementById('adminView').style.display = 'flex';
    document.getElementById('store').style.display = 'none';
    document.getElementById('waFloat').style.display = 'none';
    refreshAdmin();
    listenOrders();
  }
});

window.doLogin = async function(){
  const email = document.getElementById('al-u').value.trim();
  const pass  = document.getElementById('al-p').value;
  if(!email||!pass){ toast('Enter email and password'); return; }
  try {
    document.getElementById('alBtn').textContent = 'Signing in...';
    await signInWithEmailAndPassword(auth, email, pass);
  } catch(e){
    document.getElementById('alErr').style.display = 'block';
    document.getElementById('alErr').textContent = 'Wrong credentials: '+e.message;
    document.getElementById('alBtn').textContent = 'Sign In';
  }
};

window.doLogout = async function(){
  await signOut(auth);
  IS_ADMIN = false;
  document.getElementById('adminView').style.display = 'none';
  document.getElementById('store').style.display = 'block';
  document.getElementById('waFloat').style.display = 'flex';
  applySettings();
  renderFeatured();
  renderMain();
};

window.openAL  = () => document.getElementById('adminLogin').classList.add('on');
window.closeAL = () => document.getElementById('adminLogin').classList.remove('on');

// ════════════════════════════════════════════
// PAGE ROUTING
// ════════════════════════════════════════════
window.goP = function(pg){
  document.querySelectorAll('.pg').forEach(p=>p.classList.remove('on'));
  const el = document.getElementById('pg-'+pg);
  if(el){ el.classList.add('on'); window.scrollTo({top:0,behavior:'smooth'}); }
  if(pg==='home')    renderFeatured();
  if(pg==='listing') renderMain();
};

window.fGo = function(cat){
  FILT = cat==='all' ? [...PRODS] : PRODS.filter(p=>p.cat===cat);
  const t = cat==='all'?'All Jewellery':cat;
  const el1=document.getElementById('lTitle'), el2=document.getElementById('lbread'), el3=document.getElementById('lCount');
  if(el1) el1.textContent=t;
  if(el2) el2.textContent=t;
  if(el3) el3.textContent='Showing '+FILT.length+' products';
  goP('listing');
  setTimeout(()=>{
    document.querySelectorAll('.f-tab').forEach(t=>t.classList.remove('on'));
    document.querySelectorAll('.f-tab').forEach(t=>{
      if(t.textContent.trim()===cat||(cat==='all'&&t.textContent.trim()==='All')) t.classList.add('on');
    });
    renderMain();
  },50);
};

// ════════════════════════════════════════════
// PRODUCT RENDERING
// ════════════════════════════════════════════
function pCard(p, idx){
  const pr   = calcPrice(p);
  const inW  = WISHLIST.has(p.id);
  const sC   = p.stock===0?'av-out':p.stock<=3?'av-low':'av-in';
  const sL   = p.stock===0?'Out of Stock':p.stock<=3?'Only '+p.stock+' left':'In Stock';
  const tgH  = p.tag ? `<div class="prod-tag${p.tag==='New'||p.tag==='Bridal'?' new':p.tag==='Sold Out'?' sold':''}">${p.tag}</div>` : '';
  return `<div class="prod-cell" onclick="openDet('${p.id}')">
    <div class="prod-img-wrap">
      <img src="${p.img}" alt="${p.name}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=600&q=80'">
      ${tgH}
      <button class="prod-wish${inW?' on':''}" onclick="toggleWish(event,'${p.id}')">
        <svg viewBox="0 0 24 24" fill="${inW?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8"><path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"/></svg>
      </button>
      <div class="prod-hover-bar">
        <button class="prod-hbtn" onclick="event.stopPropagation();addCart('${p.id}')">${p.stock===0?'NOTIFY ME':'ADD TO CART'}</button>
        <button class="prod-hbtn sec" onclick="event.stopPropagation();openDet('${p.id}')">VIEW DETAILS</button>
      </div>
    </div>
    <div class="prod-body">
      <div class="prod-cat">${p.cat}</div>
      <div class="prod-name">${p.name}</div>
      <div class="prod-tags-row"><span class="prod-tag-chip">${p.metal}</span><span class="prod-tag-chip">${p.wt}g</span></div>
      <div class="prod-price-row">
        <div><span class="prod-price">${fmt(pr.tot)}</span><span class="prod-gst"> incl. GST</span></div>
        <span class="prod-avail ${sC}">${sL}</span>
      </div>
    </div>
  </div>`;
}

function renderFeatured(){
  const g = document.getElementById('featGrid');
  if(g) g.innerHTML = PRODS.length
    ? PRODS.slice(0,8).map(p=>pCard(p)).join('')
    : '<div style="grid-column:1/-1;text-align:center;padding:40px;color:#888">Loading products...</div>';
}

function renderMain(){
  const g = document.getElementById('mainGrid');
  if(g) g.innerHTML = FILT.length
    ? FILT.map(p=>pCard(p)).join('')
    : '<div style="grid-column:1/-1;text-align:center;padding:60px;color:#888">No products found</div>';
}

window.filterP = function(cat, btn){
  document.querySelectorAll('.f-tab').forEach(t=>t.classList.remove('on'));
  if(btn) btn.classList.add('on');
  FILT = cat==='all' ? [...PRODS] : PRODS.filter(p=>p.cat===cat);
  const lT=document.getElementById('lTitle'), lC=document.getElementById('lCount');
  if(lT) lT.textContent = cat==='all'?'All Jewellery':cat;
  if(lC) lC.textContent = 'Showing '+FILT.length+' products';
  renderMain();
};

window.sortP = function(v){
  if(v==='low')  FILT.sort((a,b)=>calcPrice(a).tot-calcPrice(b).tot);
  if(v==='high') FILT.sort((a,b)=>calcPrice(b).tot-calcPrice(a).tot);
  if(v==='name') FILT.sort((a,b)=>a.name.localeCompare(b.name));
  renderMain();
};

