window.setThumb = function(el,img){
  document.querySelectorAll('.det-thumb').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');
  const di=document.getElementById('dImg'); if(di) di.src=img;
};

// ════════════════════════════════════════════
// CART
// ════════════════════════════════════════════
window.openCart  = () => { document.getElementById('cartBg').classList.add('on'); document.getElementById('cartDrawer').classList.add('on'); renderCart(); };
window.closeCart = () => { document.getElementById('cartBg').classList.remove('on'); document.getElementById('cartDrawer').classList.remove('on'); };

window.addCart = function(prodId){
  const p = PRODS.find(x=>x.id===prodId);
  if(!p||p.stock===0){ toast('This item is out of stock'); return; }
  if(!CART.find(c=>c.id===p.id)) CART.push({...p});
  updBadge(); toast('✅ Added: '+p.name);
};

window.removeCart = function(id){
  CART = CART.filter(c=>c.id!==id); renderCart(); updBadge();
};

function updBadge(){
  const n=CART.length;
  const el=document.getElementById('cCount'); if(el) el.textContent=n;
  const bd=document.getElementById('cBadge'); if(bd) bd.textContent=n+' item'+(n!==1?'s':'');
}

function renderCart(){
  const body=document.getElementById('cartBody'), ft=document.getElementById('cartFt');
  if(!CART.length){
    body.innerHTML=`<div class="cart-empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 01-8 0"/></svg><h3>Your cart is empty</h3><p>Add jewellery to start shopping</p><button class="btn-hero" style="margin-top:14px" onclick="closeCart();fGo('all')">Shop Now</button></div>`;
    ft.classList.add('hide'); return;
  }
  ft.classList.remove('hide');
  body.innerHTML=CART.map(p=>{
    const pr=calcPrice(p);
    return `<div class="c-item"><div class="c-item-img"><img src="${p.img}" alt="${p.name}" onerror="this.src='${p.img}'"></div><div class="c-item-body"><div class="c-item-name">${p.name}</div><div class="c-item-meta">${p.metal} · ${p.wt}g · ${p.id}</div><div class="c-item-price">${fmt(pr.tot)}</div></div><button class="c-item-rm" onclick="removeCart('${p.id}')">✕</button></div>`;
  }).join('');
  const totEl=document.getElementById('cartTot');
  if(totEl) totEl.textContent=fmt(CART.reduce((s,p)=>s+calcPrice(p).tot,0));
}

