window.toggleWish = function(e,id){
  e.stopPropagation();
  WISHLIST.has(id)?WISHLIST.delete(id):WISHLIST.add(id);
  toast(WISHLIST.has(id)?'♥ Saved to wishlist':'Removed from wishlist');
  const b=document.getElementById('wCount');
  if(b){ b.textContent=WISHLIST.size; b.classList.toggle('hide',WISHLIST.size===0); }
  renderFeatured(); renderMain();
};

