window.openCo = function(){
  closeCart();
  const tot=CART.reduce((s,p)=>s+calcPrice(p).tot,0);
  const sumEl=document.getElementById('coSum');
  if(sumEl) sumEl.innerHTML=CART.map(p=>`<div class="co-sum-r"><span>${p.name}</span><span>${fmt(calcPrice(p).tot)}</span></div>`).join('')+`<div class="co-sum-r tot"><span>Total (incl. GST)</span><span>${fmt(tot)}</span></div>`;
  document.getElementById('coMain').classList.remove('hide');
  document.getElementById('coDone').classList.add('hide');
  document.getElementById('coModal').classList.add('on');
};
window.closeCo = () => document.getElementById('coModal').classList.remove('on');
window.selPay  = el => { document.querySelectorAll('.pay-opt').forEach(o=>o.classList.remove('on')); el.classList.add('on'); };

window.placeOrder = async function(){
  const fname = document.getElementById('cf1')?.value.trim();
  const phone = document.getElementById('cf3')?.value.trim();
  const addr  = document.getElementById('cf4')?.value.trim();
  if(!fname||!phone||!addr){ toast('Please fill in all delivery details'); return; }
  const btn = document.querySelector('#coMain .btn-place');
  if(btn) btn.textContent='Placing Order...';
  const orderData = {
    customer: { name:fname+' '+(document.getElementById('cf2')?.value||''), phone, address:addr+', '+(document.getElementById('cf5')?.value||'')+' '+(document.getElementById('cf6')?.value||'') },
    items: CART.map(p=>({ id:p.id, name:p.name, metal:p.metal, wt:p.wt, price:Math.round(calcPrice(p).tot) })),
    total: Math.round(CART.reduce((s,p)=>s+calcPrice(p).tot,0)),
    paymentMethod: document.querySelector('.pay-opt.on')?.textContent||'Card',
  };
  const orderId = await fbPlaceOrder(orderData);
  if(orderId){
    CART=[]; updBadge();
    document.getElementById('coMain').classList.add('hide');
    document.getElementById('coDone').classList.remove('hide');
    const oid=document.getElementById('orderId'); if(oid) oid.textContent='Order #'+orderId.slice(-6).toUpperCase()+' Confirmed';
    if(btn) btn.textContent='PLACE ORDER & PAY SECURELY';
  }
};

