function refreshAdmin(){
  updateDashStats();
  updateAdminRateDisplay();
  renderAdminProducts();
  renderInventory();
  renderTopProducts();
  const d=document.getElementById('avDate');
  if(d) d.textContent=new Date().toLocaleDateString('en-IN',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  const c=document.getElementById('avClock');
  if(c) c.textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});
  // Build revenue chart
  const months=['Oct','Nov','Dec','Jan','Feb','Mar'], vals=[8.2,9.4,14.1,10.8,11.5,14.2], mx=Math.max(...vals);
  const chart=document.getElementById('avChart');
  if(chart) chart.innerHTML=months.map((m,i)=>`<div class="av-bar-w"><div class="av-bar" style="height:${(vals[i]/mx)*100}px"></div><span class="av-bar-lbl">${m}</span></div>`).join('');
}

function updateDashStats(){
  const dp=document.getElementById('d-p'); if(dp) dp.textContent=PRODS.length;
  const dl=document.getElementById('d-l'); if(dl) dl.textContent=PRODS.filter(p=>p.stock>0&&p.stock<=3).length;
}

function updateAdminRateDisplay(){
  const ag24=document.getElementById('ag24'); if(ag24) ag24.textContent=fmt(RATES.gold24);
  const ag22=document.getElementById('ag22'); if(ag22) ag22.textContent=fmt(RATES.gold22);
  const asv=document.getElementById('asv');   if(asv)  asv.textContent='₹'+RATES.silver;
}

function renderAdminProducts(){
  const tbl=document.getElementById('ptable');
  if(!tbl) return;
  tbl.innerHTML=PRODS.map(p=>{
    const pr=calcPrice(p), sc=p.stock===0?'out':p.stock<=3?'low':'in', sl=p.stock===0?'Out':p.stock<=3?'Low ('+p.stock+')':'In Stock';
    return `<tr>
      <td>${p.id}</td>
      <td style="display:flex;align-items:center;gap:9px;color:rgba(255,255,255,.8)"><img src="${p.img}" style="width:32px;height:32px;object-fit:cover" onerror="this.style.display='none'">${p.name}</td>
      <td style="color:rgba(255,255,255,.45)">${p.cat}</td>
      <td style="color:rgba(255,255,255,.45)">${p.metal}</td>
      <td style="color:rgba(255,255,255,.45)">${p.wt}g</td>
      <td style="color:var(--gold);font-weight:700">${fmt(pr.tot)}</td>
      <td><span class="a-pill ${sc}">${sl}</span></td>
      <td>
        <button class="av-btn-o" style="padding:4px 12px;font-size:10px;margin-right:4px" onclick="openEdit('${p.id}')">Edit</button>
        <button class="av-btn-d" onclick="confirmDelete('${p.id}','${p.name}')">Del</button>
      </td>
    </tr>`;
  }).join('');
}

function renderInventory(){
  const iI=PRODS.filter(p=>p.stock>3).length, lO=PRODS.filter(p=>p.stock>0&&p.stock<=3).length, oO=PRODS.filter(p=>p.stock===0).length;
  ['inv-i','inv-l','inv-o','inv-t'].forEach((id,i)=>{ const el=document.getElementById(id); if(el) el.textContent=[iI,lO,oO,PRODS.length][i]; });
  const tbl=document.getElementById('inv-table');
  if(!tbl) return;
  tbl.innerHTML=PRODS.map(p=>{
    const sc=p.stock===0?'out':p.stock<=3?'low':'in', sl=p.stock===0?'Out of Stock':p.stock<=3?'Low Stock':'In Stock';
    const pct=Math.min(100,(p.stock/15)*100), bc=p.stock===0?'#f88':p.stock<=3?'#f6a623':'#6fcf97';
    return `<tr>
      <td>${p.id}</td><td style="color:rgba(255,255,255,.75)">${p.name}</td>
      <td style="color:rgba(255,255,255,.4)">${p.cat}</td>
      <td style="color:#fff;font-weight:700">${p.stock}
        <div style="height:4px;background:rgba(255,255,255,.07);border-radius:2px;overflow:hidden;margin-top:4px"><div style="width:${pct}%;height:100%;background:${bc};border-radius:2px"></div></div>
      </td>
      <td><span class="a-pill ${sc}">${sl}</span></td>
      <td>
        <input type="number" value="${p.stock}" id="si-${p.id}" style="width:52px;background:rgba(255,255,255,.07);border:1px solid #2e2e2e;color:#fff;padding:5px 8px;font-size:12px">
        <button class="av-btn" style="padding:5px 12px;font-size:10px;margin-left:6px" onclick="setStock('${p.id}','${p._docId}')">Set</button>
      </td>
    </tr>`;
  }).join('');
}

window.setStock = async function(prodId, docId){
  const inp=document.getElementById('si-'+prodId);
  if(!inp) return;
  const n=parseInt(inp.value);
  if(isNaN(n)||n<0){ toast('❌ Enter a valid number'); return; }
  const ok = await fbUpdateStock(docId, n);
  if(ok) toast('✅ Stock for '+prodId+' updated to '+n+' — saved to database!');
};

window.confirmDelete = async function(prodId, name){
  if(!confirm('Delete "'+name+'"?\nThis permanently removes it from your store and database.')) return;
  const p=PRODS.find(x=>x.id===prodId);
  if(!p){ toast('Product not found'); return; }
  const ok=await fbDeleteProduct(p._docId);
  if(ok) toast('✅ "'+name+'" deleted from store and database.');
};

function renderTopProducts(){
  const el=document.getElementById('topP');
  if(!el) return;
  const sorted=[...PRODS].sort((a,b)=>calcPrice(b).tot-calcPrice(a).tot).slice(0,4);
  el.innerHTML=sorted.map((p,i)=>`<div style="display:flex;align-items:center;gap:10px;padding:9px;background:rgba(255,255,255,.04);border:1px solid #242424"><span style="font-family:'Playfair Display',serif;font-size:16px;font-weight:700;color:var(--gold);width:20px">${i+1}</span><img src="${p.img}" style="width:32px;height:32px;object-fit:cover" onerror="this.style.display='none'"><span style="font-size:12px;color:rgba(255,255,255,.6);flex:1">${p.name}</span><span style="font-family:'Playfair Display',serif;font-size:14px;color:var(--gold);font-weight:600">${fmt(calcPrice(p).tot)}</span></div>`).join('');
}

function renderOrderTables(orders){
  const sc={Pending:'pending',Shipped:'shipped',Delivered:'delivered',Cancelled:'cancelled'};
  const rowFn = (o,showAction) => `<tr>
    <td>#${o._docId?.slice(-6).toUpperCase()||'--'}</td>
    <td style="color:rgba(255,255,255,.65)">${o.customer?.name||'--'}</td>
    <td style="color:rgba(255,255,255,.65)">${o.items?.map(i=>i.name).join(', ').slice(0,30)||'--'}</td>
    <td style="color:var(--gold);font-weight:700">₹${o.total?.toLocaleString('en-IN')||'--'}</td>
    <td><span class="a-pill ${sc[o.status]||'pending'}">${o.status||'Pending'}</span></td>
    <td style="color:rgba(255,255,255,.3)">${o.createdAt?.toDate?.().toLocaleDateString('en-IN')||'--'}</td>
    ${showAction?`<td>
      <select onchange="fbUpdateOrderStatus('${o._docId}',this.value)" style="background:#222;border:1px solid #333;color:#fff;padding:4px 8px;font-size:11px;font-family:'Lato',sans-serif">
        <option ${o.status==='Pending'?'selected':''}>Pending</option>
        <option ${o.status==='Shipped'?'selected':''}>Shipped</option>
        <option ${o.status==='Delivered'?'selected':''}>Delivered</option>
        <option ${o.status==='Cancelled'?'selected':''}>Cancelled</option>
      </select>
    </td>`:''}
  </tr>`;
  const dEl=document.getElementById('d-orders');  if(dEl) dEl.innerHTML=orders.slice(0,5).map(o=>rowFn(o,false)).join('');
  const aEl=document.getElementById('all-o');      if(aEl) aEl.innerHTML=orders.map(o=>rowFn(o,true)).join('');
  // Update dashboard orders count
  const doEl=document.getElementById('dash-order-count'); if(doEl) doEl.textContent=orders.filter(o=>o.status==='Pending').length+' pending';
}
window.fbUpdateOrderStatus = fbUpdateOrderStatus;

