window.saveRates = async function(){
  const g24=parseFloat(document.getElementById('pc24')?.value)||RATES.gold24;
  const g22=parseFloat(document.getElementById('pc22')?.value)||RATES.gold22;
  const g18=parseFloat(document.getElementById('pc18')?.value)||RATES.gold18;
  const sv =parseFloat(document.getElementById('pcsv')?.value)||RATES.silver;
  const ok = await fbSaveRates({gold24:g24,gold22:g22,gold18:g18,silver:sv,mode:'manual'});
  if(ok) toast('✅ Metal rates saved to database! All prices updated across the store.');
};

window.autoCalc = function(){
  const g24=parseFloat(document.getElementById('pc24')?.value)||7420;
  const el22=document.getElementById('pc22'), el18=document.getElementById('pc18');
  if(el22) el22.value=Math.round(g24*.9166);
  if(el18) el18.value=Math.round(g24*.75);
};

