function syncSettingsForm(){
  const s=SETTINGS;
  const f=(id,v)=>{ const el=document.getElementById(id); if(el) el.value=v; };
  f('s-name', s.storeName); f('s-gst',  s.gst);
  f('s-phone',s.phone);     f('s-wa',   s.whatsapp);
  f('s-email',s.email);     f('s-city', s.city);
  f('s-addr', s.address);   f('s-hours',s.hours);
}

window.saveSettings = async function(){
  const v=(id)=>{ const el=document.getElementById(id); return el?el.value.trim():''; };
  const newSettings = {
    storeName: v('s-name') || SETTINGS.storeName,
    gst:       v('s-gst')  || SETTINGS.gst,
    phone:     v('s-phone')|| SETTINGS.phone,
    whatsapp:  v('s-wa').replace(/[^0-9]/g,'') || SETTINGS.whatsapp,
    email:     v('s-email')|| SETTINGS.email,
    city:      v('s-city') || SETTINGS.city,
    address:   v('s-addr') || SETTINGS.address,
    hours:     v('s-hours')|| SETTINGS.hours,
  };
  SETTINGS = {...SETTINGS, ...newSettings};
  const ok = await fbSaveSettings(newSettings);
  if(ok){
    applySettings();
    const msg=document.getElementById('s-saved-msg');
    if(msg){
      msg.textContent='✅ Saved to database! '+SETTINGS.storeName+' | '+SETTINGS.phone;
      msg.style.display='block';
      setTimeout(()=>msg.style.display='none',6000);
    }
    toast('✅ Settings saved to Firebase! Changes are permanent and live.');
  }
};

