window.openEdit = function(prodId){
  const p=PRODS.find(x=>x.id===prodId);
  if(!p) return;
  const f=(id,v)=>{ const el=document.getElementById(id); if(el) el.value=v; };
  f('edit-docid', p._docId); f('edit-id',p.id); f('edit-nm',p.name);
  f('edit-cat',p.cat);       f('edit-met',p.metal);
  f('edit-wt',p.wt);         f('edit-mc',p.mc);
  f('edit-stk',p.stock);     f('edit-tag',p.tag||'');
  f('edit-img',p.img);       f('edit-desc',p.desc||'');
  updateEditPreview();
  document.getElementById('editModal').style.display='flex';
};
window.closeEdit = () => document.getElementById('editModal').style.display='none';

window.updateEditPreview = function(){
  const met=document.getElementById('edit-met')?.value||'Gold 22K';
  const wt=parseFloat(document.getElementById('edit-wt')?.value)||0;
  const mc=parseFloat(document.getElementById('edit-mc')?.value)||0;
  const rate=met.includes('24K')?RATES.gold24:met.includes('22K')?RATES.gold22:met.includes('18K')?RATES.gold18:met.includes('Silver')?RATES.silver:RATES.gold18;
  const mv=wt*rate, mk=wt*mc, s=mv+mk, gst=s*.03, tot=s+gst;
  const set=(id,v)=>{ const el=document.getElementById(id); if(el) el.textContent=v; };
  set('ep-mv',fmt(mv)); set('ep-mk',fmt(mk)); set('ep-gst',fmt(gst)); set('ep-tot',fmt(tot));
};

window.saveEdit = async function(){
  const docId=document.getElementById('edit-docid')?.value;
  const nm=document.getElementById('edit-nm')?.value.trim();
  if(!nm||!docId){ toast('Missing data'); return; }
  const img=document.getElementById('edit-img')?.value.trim()||'';
  const updated = {
    id:   document.getElementById('edit-id')?.value.trim(),
    name: nm,
    cat:  document.getElementById('edit-cat')?.value,
    metal:document.getElementById('edit-met')?.value,
    wt:   parseFloat(document.getElementById('edit-wt')?.value)||0,
    mc:   parseFloat(document.getElementById('edit-mc')?.value)||0,
    stock:parseInt(document.getElementById('edit-stk')?.value)||0,
    tag:  document.getElementById('edit-tag')?.value||'',
    img:  img, imgs:[img,img,img,img],
    desc: document.getElementById('edit-desc')?.value.trim()||'',
  };
  try {
    await updateDoc(doc(db,'products',docId), {...updated, updatedAt:serverTimestamp()});
    closeEdit();
    toast('✅ "'+nm+'" updated in database! Live on store.');
  } catch(e){ toast('❌ '+e.message); }
};

