let tTimer;
window.toast = function(m){
  const el=document.getElementById('toast'); if(!el) return;
  el.textContent=m; el.classList.add('on');
  clearTimeout(tTimer); tTimer=setTimeout(()=>el.classList.remove('on'),3500);
};

