// INIT
// ════════════════════════════════════════════
document.addEventListener('DOMContentLoaded', () => {
  // Build hero dots
  const n=document.querySelectorAll('.hero-slide').length;
  const dotsEl=document.getElementById('heroDots');
  if(dotsEl) dotsEl.innerHTML=Array.from({length:n},(_,i)=>`<button class="hdot${i===0?' on':''}" onclick="HERO_IDX=${i-1};heroMove(1)"></button>`).join('');
  setInterval(()=>heroMove(1), 5000);

  buildMarquee();
  applySettings();

  // Start Firebase listeners
  startListeners();

  // Admin clock
  setInterval(()=>{
    const c=document.getElementById('avClock'); if(c) c.textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});
  }, 30000);
});
